const express = require('express');
const { z } = require('zod');
const { StripeBillingService } = require('../services/stripe');
const { OrganizationMember } = require('../models/org');

const app = express();
app.use(express.json());

const upgradeSchema = z.object({
  organizationId: z.string().uuid(),
  targetTier: z.enum(['PRO_MONTHLY', 'ENTERPRISE_ANNUAL']),
  seatsCount: z.number().int().min(1).max(500)
});

const validateUpgradeRequest = (req, res, next) => {
  const result = upgradeSchema.safeParse(req.body);
  if (!result.success) {
    return res.status(400).json({ errors: result.error.format() });
  }
  req.validatedBody = result.data;
  next();
};

app.post('/api/billing/subscriptions/upgrade', validateUpgradeRequest, async (req, res) => {
  if (!req.user || !req.user.id) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { organizationId, targetTier, seatsCount } = req.validatedBody;

  // Enforce that the authenticated user is a billing administrator for the target organization
  const membership = await OrganizationMember.findOne({
    where: {
      userId: req.user.id,
      organizationId: organizationId,
      role: 'BILLING_ADMIN'
    }
  });

  if (!membership) {
    return res.status(403).json({ error: 'Access denied: caller is not a billing administrator for this organization' });
  }

  try {
    const subscription = await StripeBillingService.modifyOrgPlan(
      organizationId,
      targetTier,
      seatsCount
    );
    res.json({ success: true, subscription });
  } catch (err) {
    res.status(500).json({ error: 'Subscription upgrade failed' });
  }
});

app.listen(7001);
